vertexShader:
attribute float aEnd; uniform float uTime; uniform vec3 uCam; varying float vA; varying float vEnd;
      void main(){ vec3 p = position; float sp = 21. + fract(p.x * 13.1) * 6.; p.y = mod(p.y - uTime * sp, 34.); p.x += (34. - p.y) * .2;
        vec3 w = vec3(mod(p.x - uCam.x + 35., 70.) - 35. + uCam.x, p.y - 12. + uCam.y, mod(p.z - uCam.z + 35., 70.) - 35. + uCam.z);
        float e = floor(aEnd + .5); w += e * vec3(-.07, .62, 0.); vEnd = e;
        float d = length(w - uCam); vA = smoothstep(34., 4., d) * smoothstep(.5, 2.5, d);
        gl_Position = projectionMatrix * viewMatrix * vec4(w, 1.); }
